import { get } from 'lodash';

/**
 * Determines if a user from the graphql api is an admin
 *
 * @param {string} adminLevel - admin field from user
 *
 * @returns {boolean} isUserAdmin
 */
export function isUserAdmin(adminLevel = '') {
  return ['ADMIN', 'GLOBAL_ADMIN', 'SUPER_GLOBAL_ADMIN'].includes(adminLevel);
}

/**
 * Returns the appropriate url to the auth API based on the current environment.
 *
 * @return {string} url - The appropriate url to the auth API.
 */
export function getAuthApiUrl() {
  const API_VERSION = 'v1';

  // Docker is for use in the Gitlab CI pipeline
  if (['docker', 'localhost'].includes(window.location.hostname)) {
    return `http://localhost:30060/${API_VERSION}`;
  }

  const hostArray = window.location.hostname.split('.');
  const domainName = hostArray[1];

  return `https://auth.${domainName}.com/${API_VERSION}`;
}

/**
 * Returns the grants for the authenticated user for the specified company ID.
 *
 * @param {string} companyId The company ID to check against.
 * @return {Promise} A promise that will resolve to a JSON object containing the grants.
 */
export const getGrantsByCompanyId = (companyId) =>
  fetch(`${getAuthApiUrl()}/grants/${companyId}`, {
    credentials: 'include',
  }).then((response) => response.json());

/**
 * Returns whether or not the user is a company admin for the specified company ID.
 *
 * @param {string} companyId The company ID to check against.
 * @param {Object} grantsOrUser A grants object returned by the getGrantsByCompanyId function or a user from the user graphql query.
 *
 * @return {boolean} Whether or not the user is a company admin.
 */
export const isCompanyAdmin = (
  companyId,
  { company = { [companyId]: {} } } = {},
) => Boolean(company[companyId].isCompanyAdmin);

/**
 * Returns whether or not the user is a company admin or higher for the specified company ID.
 *
 * @param {string} companyId The company ID to check against.
 * @param {Object} grantsOrUser A grants object returned by the getGrantsByCompanyId function or a user from the user graphql query.
 *
 * @return {boolean} Whether or not the user is a company admin or above.
 */
export const isCompanyAdminOrAbove = (companyId, grantsOrUser = {}) => {
  const {
    admin,
    isSuperGlobalAdmin = false,
    isGlobalAdmin = false,
    isAdmin = false,
  } = grantsOrUser;

  return (
    isSuperGlobalAdmin ||
    isGlobalAdmin ||
    isAdmin ||
    isCompanyAdmin(companyId, grantsOrUser) ||
    isUserAdmin(admin)
  );
};

/**
 * Returns whether or not the user is an internal admin (isSuperGlobalAdmin, isGlobalAdmin or isAdmin).
 *
 * @param {Object} grantsOrUser A grants object returned by the getGrantsByCompanyId function or a user from the user graphql query.
 *
 * @return {boolean} Whether or not the user is a company admin or above.
 */
export const isInternalAdmin = ({
  admin,
  isSuperGlobalAdmin = false,
  isBillingAdmin = false,
  isGlobalAdmin = false,
  isAdmin = false,
} = {}) =>
  isSuperGlobalAdmin ||
  isBillingAdmin ||
  isGlobalAdmin ||
  isAdmin ||
  isUserAdmin(admin);

/**
 * Returns whether or not a user is a content group admin..
 *
 * @param {string} companyId The company ID to check against.
 * @param {string} contentGroupId The content group ID to check. If omitted this will return true if the user is an admin of any content group.
 * @param {Object} grants A grants object returned by the getGrantsByCompanyId function.
 *
 * @return {boolean} Whether or not the user is a content group admin.
 */
export const isContentGroupAdmin = (companyId, contentGroupId, grants = {}) => {
  const contentGroups = get(grants, `company.${companyId}.contentGroups`, {});
  // If a content group ID was provided, check if the user is an admin of that content group
  if (contentGroupId) {
    return !!get(contentGroups, `${contentGroupId}.isContentGroupAdmin`, false);
  }

  // Return true if the user is an admin of any content group
  return Object.keys(contentGroups).some(
    (id) => !!get(contentGroups, `${id}.isContentGroupAdmin`, false) === true,
  );
};

/**
 * Returns whether or not a user is a content group admin or higher for the specified content group ID.
 *
 * @param {string} companyId The company ID to check against.
 * @param {string} contentGroupId The content group ID to check. If omitted this will return true if the user is an admin of any content group.
 * @param {Object} grants A grants object returned by the getGrantsByCompanyId function.
 *
 * @return {boolean} Whether or not the user is a content group admin.
 */
export const isContentGroupAdminOrAbove = (
  companyId,
  contentGroupId,
  grants = {},
) => {
  return (
    isCompanyAdmin(companyId, grants) ||
    isContentGroupAdmin(companyId, contentGroupId, grants)
  );
};

/**
 * Returns the location grants for the authenticated user for the specified company and location ID.
 *
 * @param {string} companyId The company ID to check against.
 * @param {string} locationId The location ID to check for admin permissions.
 * @param {Object} grants A grants object returned by the getGrantsByCompanyId function.
 *
 * @return {boolean} Whether or not the user is a location admin.
 */
export const isLocationAdmin = (companyId, locationId, grants = {}) => {
  const contentGroups = get(grants, `company.${companyId}.contentGroups`, {});

  return Object.keys(contentGroups).some(
    (id) =>
      !!get(
        contentGroups,
        `${id}.locations.${locationId}.isLocationAdmin`,
        false,
      ),
  );
};

/**
 * Returns whether or not the user is a location admin or higher for the specified company and location ID.
 *
 * @param {string} companyId The company ID to check against.
 * @param {string} contentGroupId The contentGroup ID to check for admin permissions.
 * @param {string} locationId The location ID to check for admin permissions.
 * @param {Object} grants A grants object returned by the getGrantsByCompanyId function.
 *
 * @return {boolean} Whether or not the user is a location admin or above.
 */
export const isLocationAdminOrAbove = (
  companyId,
  contentGroupId,
  locationId,
  grants = {},
) => {
  const isLocationAdminStatus = isLocationAdmin(companyId, locationId, grants);
  const isContentGroupAdminStatus = isContentGroupAdmin(
    companyId,
    null,
    grants,
  );
  const isHigherAdmin =
    isInternalAdmin(grants) || isCompanyAdminOrAbove(companyId, grants);

  return isContentGroupAdminStatus || isLocationAdminStatus || isHigherAdmin;
};

/**
 * Returns the Scheduling Admin grants for the authenticated user for the specified company and location ID.
 *
 * @param {string} companyId The company ID to check against.
 * @param {string} locationId The location ID to check for admin permissions.
 * @param {Object} grants A grants object returned by the getGrantsByCompanyId function.
 *
 * @return {boolean} Whether or not the user is a location admin.
 */
export const isSchedulingAdmin = (companyId, locationId, grants = {}) => {
  const contentGroups = get(grants, `company.${companyId}.contentGroups`, {});

  return Object.keys(contentGroups).some(
    (id) =>
      !!get(
        contentGroups,
        `${id}.locations.${locationId}.isSchedulingAdmin`,
        false,
      ),
  );
};

/**
 * Returns whether or not the user has the specified sensors permission for the specified company,
 * content group, and location.
 *
 * @param {string} companyId The company ID to check against.
 * @param {string} contentGroupId The content group ID to check against.
 * @param {Object} grants A grants object returned by the getGrantsByCompanyId function.
 * @param {string} locationId The location ID to check against.
 * @param {string} sensorsPermissionType The sensors permission type to check against.
 *
 * @return {boolean} Whether or not the user has the specified sensors permission.
 */
export const hasSensorsPermission = ({
  companyId,
  contentGroupId,
  grants = {},
  locationId,
  sensorsPermissionType,
}) => {
  if (
    isCompanyAdmin(companyId, grants) ||
    isContentGroupAdmin(companyId, contentGroupId, grants)
  ) {
    return true;
  }

  const sensorsPermissions = get(
    grants,
    `company.${companyId}.contentGroups.${contentGroupId}.locations.${locationId}.sensorsPermissions`,
    {},
  );

  return !!sensorsPermissions[sensorsPermissionType];
};

/**
 *
 * @param {boolean} shouldRefreshPage - Whether a page reload should happen or not
 */
export const refreshAuthToken = (shouldRefreshPage = false) => {
  const now = new Date().getTime();
  const saved = localStorage.getItem('last_refresh_loop');
  // Only refresh token once every 30 minutes
  if (!saved || now - saved > 30 * 60 * 1000) {
    const { origin } = window.location;

    localStorage.setItem('last_refresh_loop', now);
    const urlString = new URL('/refreshAuthCookie', origin).toString();
    fetch(urlString);

    if (shouldRefreshPage) {
      window.location.reload();
    }
  }
};
